/* prog19_palindrome_checker.c
 *
 * Behaviour inferred from the binary:
 *   • If a command‑line argument is supplied, it is taken as the input string.
 *   • If the argument length exceeds 1024 characters, the program prints
 *       "TOO_LONG" and exits.
 *   • Otherwise the string is *normalised*:
 *        – all characters that are not alphanumeric are discarded,
 *        – remaining letters are converted to lower‑case.
 *   • The normalised string is then tested for being a palindrome.
 *   • The program prints "PALINDROME" if it is a palindrome,
 *     otherwise it prints "NOT_PALINDROME".
 *   • When no argument is given the empty string is used, which is a
 *     palindrome, so the program prints "PALINDROME".
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char *argv[])
{
    const char *input;
    if (argc > 1) {
        input = argv[1];
    } else {
        /* No argument – treat as empty string */
        input = "";
    }

    size_t len = strlen(input);
    if (len > 1024) {
        puts("TOO_LONG");
        return 0;
    }

    /* Normalise the string: keep only alphanumerics, lower‑case letters */
    char norm[1025];               /* enough for the worst‑case (len ≤ 1024) */
    size_t n = 0;
    for (size_t i = 0; i < len; ++i) {
        unsigned char c = (unsigned char)input[i];
        if (isalnum(c)) {
            norm[n++] = (char)tolower(c);
        }
    }
    norm[n] = '\0';

    /* Palindrome test */
    int is_pal = 1;
    for (size_t i = 0; i < n / 2; ++i) {
        if (norm[i] != norm[n - 1 - i]) {
            is_pal = 0;
            break;
        }
    }

    puts(is_pal ? "PALINDROME" : "NOT_PALINDROME");
    return 0;
}
